        }
        button:hover {
            background-color: #0056b3;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Random Joke Generator</h1>
        <div id="jokeDisplay">Click the button to get a joke!</div>
        <button id="getJokeBtn">Get a Joke</button>
    </div>

    <script>
        const jokes = [
            "Why don't scientists trust atoms? Because they make up everything!",
            "What do you call a fish with no eyes? Fsh!",
            "Why did the scarecrow win an award? Because he was outstanding in his field!",
            "Why don't eggs tell jokes? They'd crack each other up!"
        ];

        const jokeDisplay = document.getElementById('jokeDisplay');
        const getJokeBtn = document.getElementById('getJokeBtn');

        getJokeBtn.addEventListener('click', () => {
            // Generate a random index from 0 to jokes.length - 1
            const randomIndex = Math.floor(Math.random() * jokes.length);

            // Get the joke at the random index
            const randomJoke = jokes[randomIndex];

            // Display the joke
            jokeDisplay.textContent = randomJoke;
        });
    </script>
</body>
</html>
```

